template <typename T, typename Char, typename Enable = void>
struct range_formatter;

template <typename T, typename Char>
struct range_formatter<
    T, Char,
    enable_if_t<conjunction<std::is_same<T, remove_cvref_t<T>>,
                            is_formattable<T, Char>>::value>> {
 private:
  detail::range_formatter_type<Char, T> underlying_;
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '['>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ']'>{};

 public:
  FMT_CONSTEXPR range_formatter() {}

  FMT_CONSTEXPR auto underlying() -> detail::range_formatter_type<Char, T>& {
    return underlying_;
  }

  FMT_CONSTEXPR void set_separator(basic_string_view<Char> sep) {
    separator_ = sep;
  }

  FMT_CONSTEXPR void set_brackets(basic_string_view<Char> open,
                                  basic_string_view<Char> close) {
    opening_bracket_ = open;
    closing_bracket_ = close;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    auto end = ctx.end();
    bool has_nested_specs = false;
    bool consumed_range_prefix = false;

    if (it == end) {
      detail::maybe_set_debug_format(underlying_, true);
      ctx.advance_to(it);
      return underlying_.parse(ctx);
    }

    while (it != end) {
      Char spec = *it;
      if (spec != static_cast<Char>('}')) {
        char ascii = detail::to_ascii(spec);
        Char spec_storage = spec;
        int units = detail::code_point_length(&spec_storage);
        if (units != 1) {
          report_error("invalid format specifier");
          return it;
        }

        auto alignment = detail::parse_align(ascii);
        if (alignment != align::none) {
          report_error("invalid format specifier");
          return it;
        }

        unsigned char raw = static_cast<unsigned char>(ascii);
        uint32_t cp = static_cast<uint32_t>(raw);
        bool disallowed = false;
        if (cp < 0x20) {
          disallowed = true;
        } else if (cp == 0x7f) {
          disallowed = true;
        } else if (ascii == '"') {
          disallowed = true;
        } else if (ascii == '\\') {
          disallowed = true;
        } else if (!detail::is_constant_evaluated()) {
          if (detail::needs_escape(cp)) {
            disallowed = true;
          }
        }
        if (disallowed) {
          report_error("invalid format specifier");
          return it;
        }

        if (!consumed_range_prefix) {
          if (ascii == 'n') {
            if (opening_bracket_.size() != 0) {
              auto open_ptr = opening_bracket_.begin();
              auto open_limit = opening_bracket_.end();
              while (open_ptr != open_limit) {
                ++open_ptr;
              }
              opening_bracket_ = basic_string_view<Char>();
            } else {
              opening_bracket_ = basic_string_view<Char>();
            }
            if (closing_bracket_.size() != 0) {
              auto close_ptr = closing_bracket_.begin();
              auto close_limit = closing_bracket_.end();
              while (close_ptr != close_limit) {
                ++close_ptr;
              }
              closing_bracket_ = basic_string_view<Char>();
            } else {
              closing_bracket_ = basic_string_view<Char>();
            }
            consumed_range_prefix = true;
            ++it;
            continue;
          }

          if (ascii == ':') {
            has_nested_specs = true;
            ++it;
            break;
          }

          if (ascii == '?') {
            auto next = it;
            ++next;
            if (next == end || *next != static_cast<Char>('s')) {
              report_error("invalid format specifier");
              return it;
            }
            report_error("invalid format specifier");
            return it;
          }

          if (ascii == 's') {
            if (!std::is_same<T, Char>::value) {
              report_error("invalid format specifier");
              return it;
            }
            report_error("invalid format specifier");
            return it;
          }

          if (ascii >= '1' && ascii <= '9') {
            int width = 0;
            auto look = it;
            while (look != end) {
              char digit = detail::to_ascii(*look);
              if (digit < '0' || digit > '9') {
                break;
              }
              if (width > 100000000) {
                report_error("invalid format specifier");
                return it;
              }
              width = width * 10 + (digit - '0');
              ++look;
            }
            report_error("invalid format specifier");
            return it;
          }

          report_error("invalid format specifier");
          return it;
        }

        if (ascii == ':') {
          has_nested_specs = true;
          ++it;
          break;
        }
        report_error("invalid format specifier");
        return it;
      }
      break;
    }

    if (!has_nested_specs) {
      detail::maybe_set_debug_format(underlying_, true);
    }

    ctx.advance_to(it);
    return underlying_.parse(ctx);
  }

  template <typename R, typename FormatContext>
  auto format(R&& range, FormatContext& ctx) const -> decltype(ctx.out()) {
    detail::range_mapper<buffered_context<Char>> mapper;
    auto out = ctx.out();
    out = detail::copy<Char>(opening_bracket_, out);
    int i = 0;
    auto it = detail::range_begin(range);
    auto end = detail::range_end(range);
    for (; it != end; ++it) {
      if (i > 0) out = detail::copy<Char>(separator_, out);
      ctx.advance_to(out);
      auto&& item = *it;
      out = underlying_.format(mapper.map(item), ctx);
      ++i;
    }
    out = detail::copy<Char>(closing_bracket_, out);
    return out;
  }
};

enum class range_format { disabled, map, set, sequence, string, debug_string };

namespace detail {
template <typename T>
struct range_format_kind_
    : std::integral_constant<range_format,
                             std::is_same<uncvref_type<T>, T>::value
                                 ? range_format::disabled
                             : is_map<T>::value ? range_format::map
                             : is_set<T>::value ? range_format::set
                                                : range_format::sequence> {};

template <range_format K, typename R, typename Char, typename Enable = void>
struct range_default_formatter;

template <range_format K>
using range_format_constant = std::integral_constant<range_format, K>;

template <range_format K, typename R, typename Char>
struct range_default_formatter<
    K, R, Char,
    enable_if_t<(K == range_format::sequence || K == range_format::map ||
                 K == range_format::set)>> {
  using range_type = detail::maybe_const_range<R>;
  range_formatter<detail::uncvref_type<range_type>, Char> underlying_;

  FMT_CONSTEXPR range_default_formatter() { init(range_format_constant<K>()); }

  FMT_CONSTEXPR void init(range_format_constant<range_format::set>) {
    underlying_.set_brackets(detail::string_literal<Char, '{'>{},
                             detail::string_literal<Char, '}'>{});
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::map>) {
    underlying_.set_brackets(detail::string_literal<Char, '{'>{},
                             detail::string_literal<Char, '}'>{});
    underlying_.underlying().set_brackets({}, {});
    underlying_.underlying().set_separator(
        detail::string_literal<Char, ':', ' '>{});
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::sequence>) {}

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return underlying_.parse(ctx);
  }

  template <typename FormatContext>
  auto format(range_type& range, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    return underlying_.format(range, ctx);
  }
};
}  // namespace detail

template <typename T, typename Char, typename Enable = void>
struct range_format_kind
    : conditional_t<
          is_range<T, Char>::value, detail::range_format_kind_<T>,
          std::integral_constant<range_format, range_format::disabled>> {};

template <typename R, typename Char>
struct formatter<
    R, Char,
    enable_if_t<conjunction<bool_constant<range_format_kind<R, Char>::value !=
                                          range_format::disabled>
// Workaround a bug in MSVC 2015 and earlier.
#if !FMT_MSC_VERSION || FMT_MSC_VERSION >= 1910
                            ,
                            detail::is_formattable_delayed<R, Char>
#endif
                            >::value>>
    : detail::range_default_formatter<range_format_kind<R, Char>::value, R,
                                      Char> {
};

